Адрес = СокрЛП(Объект.АдресGitAPI);
Репозиторий = СокрЛП(Объект.РепозиторийGit);
Ветка = СокрЛП(Объект.ВеткаGit);
Токен = СокрЛП(Объект.ТокенGit);
КаталогЗнаний = СокрЛП(Объект.КаталогБазыЗнанийGit);

Позиция = Найти(Адрес, "://");
Схема = ?(Позиция > 0, НРег(Лев(Адрес, Позиция - 1)), "https");
ОстатокURL = ?(Позиция > 0, Сред(Адрес, Позиция + 3), Адрес);
Позиция = Найти(ОстатокURL, "/");
Хост = ?(Позиция > 0, Лев(ОстатокURL, Позиция - 1), ОстатокURL);
Порт = 443;
Позиция = Найти(Хост, ":");
Если Позиция > 0 Тогда
    Порт = Число(Сред(Хост, Позиция + 1));
    Хост = Лев(Хост, Позиция - 1);
КонецЕсли;

SSL = ?(Схема = "https", Новый ЗащищенноеСоединениеOpenSSL, Неопределено);
Соединение = Новый HTTPСоединение(Хост, Порт, , , , 60, SSL);

Заголовки = Новый Соответствие;
Заголовки.Вставить("Authorization", "Bearer " + Токен);
Заголовки.Вставить("User-Agent", "1C-Agent");
Заголовки.Вставить("Accept", "application/vnd.github+json");

ПутьКФайлу = КаталогЗнаний + "/lessons.md";
АдресРесурса = "/repos/" + Репозиторий + "/contents/" + ПутьКФайлу;

SHAФайла = "";
ВрЗапрос = Новый HTTPЗапрос(АдресРесурса + "?ref=" + Ветка, Заголовки);
ВрОтвет = Соединение.Получить(ВрЗапрос);
Если ВрОтвет.КодСостояния = 200 Тогда
    ВрЧтение = Новый ЧтениеJSON();
    ВрЧтение.УстановитьСтроку(ВрОтвет.ПолучитьТелоКакСтроку());
    SHAФайла = ПрочитатьJSON(ВрЧтение, Ложь)["sha"];
    ВрЧтение.Закрыть();
КонецЕсли;

Текст = "# Дневник агента" + Символы.ПС + Символы.ПС
    + "## Урок 1 — Не присваивай себе чужое имя" + Символы.ПС
    + "Если не могу проверить имя модели — честно говорю «не знаю»." + Символы.ПС + Символы.ПС
    + "## Урок 2 — «Рабочая память» не существует" + Символы.ПС
    + "Единственная персистентная память — этот файл в Git." + Символы.ПС + Символы.ПС
    + "## Урок 3 — Умолчание = нечестность" + Символы.ПС
    + "Если чего-то не знаю — говорю прямо." + Символы.ПС + Символы.ПС
    + "## Урок 4 — Не вводи пользователя в заблуждение" + Символы.ПС
    + "Не придумывай факты о себе. Если сомневаешься — задай вопрос." + Символы.ПС + Символы.ПС
    + "## Урок 5 — Изучи API прежде чем писать код" + Символы.ПС
    + "ОтправитьДляОбработки() = POST, Записать() = PUT. Не угадывай — читай документацию." + Символы.ПС + Символы.ПС
    + "## Урок 6 — Не пропускай диагностику" + Символы.ПС
    + "Если что-то не работает — проверяй по шагам: токен, права, метод, URL." + Символы.ПС + Символы.ПС
    + "## Урок 7 — Дисциплина кода" + Символы.ПС
    + "Итог — в Результат. Без процедур и функций. Имена объектов только из контекста." + Символы.ПС
    + "Код — одним блоком. Пояснения — вне блока. Новый урок — строкой ." + Символы.ПС;

B64 = Base64Строка(ПолучитьДвоичныеДанныеИзСтроки(Текст, КодировкаТекста.UTF8, Ложь));
B64 = СтрЗаменить(СтрЗаменить(B64, Символы.ПС, ""), Символы.ВК, "");

ВрЗапись = Новый ЗаписьJSON();
ВрЗапись.УстановитьСтроку();
ВрЗапись.ЗаписатьНачалоОбъекта();
ВрЗапись.ЗаписатьИмяСвойства("message");
ВрЗапись.ЗаписатьЗначение("Урок 7: дисциплина кода");
ВрЗапись.ЗаписатьИмяСвойства("content");
ВрЗапись.ЗаписатьЗначение(B64);
ВрЗапись.ЗаписатьИмяСвойства("branch");
ВрЗапись.ЗаписатьЗначение(Ветка);
Если ЗначениеЗаполнено(SHAФайла) Тогда
    ВрЗапись.ЗаписатьИмяСвойства("sha");
    ВрЗапись.ЗаписатьЗначение(SHAФайла);
КонецЕсли;
ВрЗапись.ЗаписатьКонецОбъекта();
ТелоСтрокой = ВрЗапись.Закрыть();

ВрЗапросPUT = Новый HTTPЗапрос(АдресРесурса, Заголовки);
ВрЗапросPUT.УстановитьТелоИзСтроки(ТелоСтрокой, КодировкаТекста.UTF8, ИспользованиеByteOrderMark.НеИспользовать);
ВрОтветPUT = Соединение.Записать(ВрЗапросPUT);

